typedef struct Mediator Mediator;
typedef void (*Slot)(void *ctx, void *sender, int event);
struct Mediator { Slot slots[MAX]; void *ctx[MAX]; size_t n; };

static void emit(Mediator *m, void *sender, int event) {
    for (size_t i = 0; i < m->n; i++)
        m->slots[i](m->ctx[i], sender, event);
}
